CREATE TABLE "articolo" ("id_articolo" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "titolo" varchar(300) NOT NULL, "testo" text NOT NULL, "data_pubblicazione" date NOT NULL, "id_autore" integer NOT NULL REFERENCES "utenti" ("id_utente") DEFERRABLE INITIALLY DEFERRED);

