INSERT INTO "articolo" VALUES(1,'Come proteggere la tua rete dagli attacchi SMB','I protocolli SMBv1 sono la principale via di propagazione di worm come WannaCry e NotPetya. In questo articolo vedremo come disabilitare SMBv1 su Windows, applicare le patch MS17-010 e segmentare la rete per limitare la propagazione laterale.
INSERT INTO "articolo" VALUES(2,'OWASP Top 10 2021: cosa è cambiato','L''OWASP Top 10 2021 porta significative novità rispetto alla versione 2017. Broken Access Control scala al primo posto, surclassando Injection che scende al terzo. Vengono introdotte tre nuove categorie: Insecure Design (A04), Software and Data Integrity Failures (A08) e Server-Side Request Forgery (A10).
INSERT INTO "articolo" VALUES(3,'Log4Shell: anatomia di una vulnerabilità critica','CVE-2021-44228, noto come Log4Shell, è una vulnerabilità di remote code execution nel framework di logging Java Apache Log4j 2. Sfrutta la funzionalità di lookup JNDI (Java Naming and Directory Interface) per caricare classi Java arbitrarie da server remoti.
INSERT INTO "articolo" VALUES(4,'Ingegneria sociale: le 6 leve psicologiche di Cialdini','Robert Cialdini ha identificato 6 principi di influenza sociale che i social engineer sfruttano sistematicamente:
INSERT INTO "articolo" VALUES(5,'Guida al penetration testing: fasi e metodologia','Il penetration testing è un processo strutturato in fasi:
INSERT INTO "attacco" VALUES(17,'WannaCry Ransomware','Ransomware worm che sfrutta EternalBlue per propagarsi sulle reti Windows, cifrando i file e richiedendo riscatto in Bitcoin.','critica','2017-05-12','T1486','',11);
INSERT INTO "attacco" VALUES(18,'SQL Injection su login form','Iniezione di codice SQL tramite campi di login non sanitizzati per bypassare l''autenticazione o estrarre dati dal database.','alta','2022-03-15','T1190','',10);
INSERT INTO "attacco" VALUES(19,'Phishing via email CEO Fraud','Email fraudolenta che impersona il CEO per indurre dipendenti a effettuare bonifici non autorizzati o condividere credenziali.','alta','2023-01-10','T1566.001','',10);
INSERT INTO "attacco" VALUES(20,'SYN Flood DDoS','Attacco di negazione del servizio che inonda il target con pacchetti SYN TCP incompleti, esaurendo le risorse del server.','media','2021-07-20','T1498.001','',10);
INSERT INTO "attacco" VALUES(21,'NotPetya Wiper','Malware distruttivo mascherato da ransomware che sovrascrive il MBR e cifra i file, causando danni irreversibili.','critica','2017-06-27','T1561.002','',11);
INSERT INTO "attacco" VALUES(22,'Cross-Site Scripting (XSS) Reflected','Iniezione di script JavaScript tramite parametri URL che vengono riflessi nella pagina, eseguendo codice nel browser della vittima.','media','2022-09-05','T1059.007','',10);
INSERT INTO "attacco" VALUES(23,'Smishing — Falso corriere','SMS fraudolento che simula una notifica di consegna pacchi per rubare dati della carta di credito tramite sito clone.','media','2023-06-01','T1566.004','',10);
INSERT INTO "attacco" VALUES(24,'ARP Spoofing / Man in the Middle','Avvelenamento della cache ARP per intercettare il traffico tra due host sulla stessa LAN, consentendo la cattura di credenziali.','alta','2021-04-14','T1557.002','',10);
INSERT INTO "attacco" VALUES(25,'Log4Shell (CVE-2021-44228)','RCE critica in Apache Log4j tramite interpolazione JNDI in messaggi di log, sfruttabile da remoto senza autenticazione.','critica','2021-12-10','T1190','',11);
INSERT INTO "attacco" VALUES(26,'Emotet Trojan bancario','Trojan modulare distribuito via email spam che funge da dropper per altre famiglie malware (TrickBot, Ryuk).','critica','2020-11-03','T1566.001','',11);
INSERT INTO "attacco" VALUES(27,'DNS Tunneling','Uso del protocollo DNS per esfiltrare dati o creare canali C2 nascosti, sfruttando la rarità dei controlli sul traffico DNS.','media','2022-05-20','T1071.004','',10);
INSERT INTO "attacco" VALUES(28,'Vishing — Supporto tecnico falso','Telefonata fraudolenta che impersona supporto tecnico Microsoft per ottenere accesso remoto al PC della vittima.','bassa','2023-03-22','T1566.004','',10);
INSERT INTO "attacco" VALUES(29,'Broken Access Control — IDOR','Accesso diretto a oggetti tramite modifica dell''ID nella URL senza verifica dei permessi, espone dati di altri utenti.','alta','2023-08-15','T1078','',10);
INSERT INTO "attacco" VALUES(30,'Cobalt Strike Beacon','Agente C2 commerciale usato dai threat actors per post-exploitation: movimento laterale, keylogging, screenshot.','critica','2022-01-05','T1219','',11);
INSERT INTO "attacco" VALUES(31,'BGP Hijacking','Annuncio fraudolento di prefissi IP BGP per dirottare il traffico Internet attraverso infrastrutture controllate dall''attaccante.','alta','2020-08-10','T1557','',11);
INSERT INTO "attacco" VALUES(32,'Credential Stuffing','Uso di liste di credenziali trapelate da data breach per tentare l''accesso automatizzato su altri servizi, sfruttando il riuso delle password.','media','2023-11-20','T1110.004','',10);
