INSERT INTO "caso_reale" VALUES(10,'Phishing CEO BEC — Ubiquiti',2015,'Ubiquiti Networks',46700000,'CEO Fraud via email porta a trasferimento fraudolento di 46.7M USD verso conti esteri.',19);
