INSERT INTO "contromisura" VALUES(9,'Patch Management sistematico','Aggiornamento regolare di tutti i software e sistemi operativi per eliminare vulnerabilità note.','preventiva');
INSERT INTO "contromisura" VALUES(10,'Web Application Firewall (WAF)','Filtro del traffico HTTP/HTTPS per bloccare attacchi web comuni (SQLi, XSS, CSRF).','preventiva');
INSERT INTO "contromisura" VALUES(11,'Intrusion Detection System (IDS)','Monitoraggio del traffico di rete per identificare pattern di attacco noti.','rilevativa');
INSERT INTO "contromisura" VALUES(12,'Antivirus ed EDR','Rilevamento e blocco di malware tramite firme e analisi comportamentale.','rilevativa');
INSERT INTO "contromisura" VALUES(13,'Formazione anti-phishing','Training periodico per riconoscere email e messaggi di social engineering.','preventiva');
INSERT INTO "contromisura" VALUES(14,'Segmentazione di rete','Isolamento dei segmenti di rete per limitare la propagazione laterale degli attacchi.','preventiva');
INSERT INTO "contromisura" VALUES(15,'Backup e disaster recovery','Backup regolari offline/offsite per ripristino rapido dopo incidenti ransomware.','correttiva');
INSERT INTO "contromisura" VALUES(16,'Autenticazione a più fattori (MFA)','Richiesta di secondo fattore di autenticazione per accessi critici.','preventiva');
